alt:
def make_flaky(fail_times):
    state = {"calls": 0}
    def fn():
        state["calls"] += 1
        if state["calls"] <= fail_times:
            raise ConnectionError("down")
        return "ok after " + str(state["calls"])
    return fn

def retry(fn, times):
    attempt = 1
    while True:
        try:
            return fn()
        except Exception:
            if attempt >= times:
                raise
            attempt += 1
